import type { AST } from "svelte-eslint-parser"
import type { TSESTree } from "@typescript-eslint/types"
import { createRule } from "../utils"

/**
 * The list of DOM manipulating methods that should not be called directly.
 */
const domManipulatingMethods = new Set([
  "appendChild",
  "insertBefore",
  "removeChild",
  "replaceChild",
  "cloneNode",
  "adoptNode",
  "importNode",
  "normalize",
  "hasChildNodes",
  "remove",
  "before",
  "after",
  "replaceWith",
  "prepend",
  "append",
])

/**
 * The list of DOM manipulating properties that should not be assigned directly.
 */
const domManipulatingProperties = new Set([
  "textContent",
  "innerHTML",
  "innerText",
  "outerHTML",
  "children",
  "childNodes",
  "firstChild",
  "lastChild",
  "firstElementChild",
  "lastElementChild",
  "nextSibling",
  "previousSibling",
  "nextElementSibling",
  "previousElementSibling",
  "parentElement",
  "parentNode",
  "ownerDocument",
  "rootNode",
])

export default createRule("no-dom-manipulating", {
  meta: {
    docs: {
      description:
        "disallow direct DOM manipulation on elements bound with `bind:this`",
      category: "Best Practices",
      recommended: false,
    },
    schema: [],
    messages: {
      unexpectedMethodCall:
        "Don't manipulate the DOM directly. Calling '{{name}}' on an element bound with `bind:this` can cause mismatches between the actual DOM and Svelte's expected DOM.",
      unexpectedPropertyAssignment:
        "Don't manipulate the DOM directly. Assigning to '{{name}}' on an element bound with `bind:this` can cause mismatches between the actual DOM and Svelte's expected DOM.",
    },
    type: "problem",
  },
  create(context) {
    // Track variables that are bound with bind:this
    const boundVariables = new Set<string>()

    // Store potential violations to report after we've seen all bind:this directives
    const methodCalls: Array<{
      node: TSESTree.MemberExpression
      methodName: string
    }> = []
    const propertyAssignments: Array<{
      node: TSESTree.MemberExpression
      propertyName: string
    }> = []

    return {
      /**
       * Collect all bind:this directives and track the bound variable names
       */
      "SvelteDirective"(node: AST.SvelteDirective) {
        if (
          node.kind === "Binding" &&
          node.key.name.name === "this" &&
          node.expression &&
          node.expression.type === "Identifier"
        ) {
          boundVariables.add(node.expression.name)
        }
      },

      /**
       * Collect potential method call violations
       */
      "CallExpression"(node: TSESTree.CallExpression) {
        // Check if the callee is a member expression like div.remove()
        if (
          node.callee.type === "MemberExpression" &&
          node.callee.object.type === "Identifier"
        ) {
          // Check if it's calling a DOM manipulating method
          if (
            node.callee.property.type === "Identifier" &&
            domManipulatingMethods.has(node.callee.property.name)
          ) {
            methodCalls.push({
              node: node.callee,
              methodName: node.callee.property.name,
            })
          }
        }
      },

      /**
       * Collect potential property assignment violations
       */
      "AssignmentExpression"(node: TSESTree.AssignmentExpression) {
        // Check if the left side is a member expression like div.textContent = ...
        if (
          node.left.type === "MemberExpression" &&
          node.left.object.type === "Identifier"
        ) {
          // Check if it's assigning to a DOM manipulating property
          if (
            node.left.property.type === "Identifier" &&
            domManipulatingProperties.has(node.left.property.name)
          ) {
            propertyAssignments.push({
              node: node.left,
              propertyName: node.left.property.name,
            })
          }
        }
      },

      /**
       * Report violations after all nodes have been visited
       */
      "Program:exit"() {
        // Report method call violations
        for (const { node, methodName } of methodCalls) {
          if (
            node.object.type === "Identifier" &&
            boundVariables.has(node.object.name)
          ) {
            context.report({
              node,
              messageId: "unexpectedMethodCall",
              data: {
                name: methodName,
              },
            })
          }
        }

        // Report property assignment violations
        for (const { node, propertyName } of propertyAssignments) {
          if (
            node.object.type === "Identifier" &&
            boundVariables.has(node.object.name)
          ) {
            context.report({
              node,
              messageId: "unexpectedPropertyAssignment",
              data: {
                name: propertyName,
              },
            })
          }
        }
      },
    }
  },
})
